// static
bool StructTraits<::ash::scanning::mojom::ScanSource::DataView, ::ash::scanning::mojom::ScanSourcePtr>::Read(
    ::ash::scanning::mojom::ScanSource::DataView input,
    ::ash::scanning::mojom::ScanSourcePtr* output) {
  bool success = true;
  ::ash::scanning::mojom::ScanSourcePtr result(::ash::scanning::mojom::ScanSource::New());
  
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success && !input.ReadPageSizes(&result->page_sizes))
        success = false;
      if (success && !input.ReadColorModes(&result->color_modes))
        success = false;
      if (success && !input.ReadResolutions(&result->resolutions))
        success = false;
  *output = std::move(result);
  return success;
}


